versions as (select 'expected' side,value from expected union all select 'actual',value from actual),
categories as(select side,e.key category,e.value from versions v cross join lateral jsonb_each(v.value) e),
items as (
 select side,category,case when category='view' then 'view' else coalesce(item->>'table',item->>'name','')||'/'||coalesce(item->>'column',item->>'args',item->>'name','')||'/'||coalesce(item->>'role','')||'/'||coalesce(item->>'privilege','') end object_name,item
 from categories cross join lateral jsonb_array_elements(case when jsonb_typeof(value)='array' then value else jsonb_build_array(value) end) item
), hashes as (
 select side,'category' kind,category,'' object_name,'' attribute,encode(sha256(convert_to(value::text,'UTF8')),'hex') digest from categories
 union all select side,'attribute',category,object_name,a.key,encode(sha256(convert_to(a.value::text,'UTF8')),'hex') from items cross join lateral jsonb_each(case when jsonb_typeof(item)='object' then item else jsonb_build_object('definition',item) end) a
), differences as (
 select coalesce(e.kind,a.kind) kind,coalesce(e.category,a.category) category,coalesce(e.object_name,a.object_name) object_name,coalesce(e.attribute,a.attribute) attribute,e.digest expected_sha256,a.digest actual_sha256
 from (select * from hashes where side='expected') e full join (select * from hashes where side='actual') a using(kind,category,object_name,attribute)
 where e.digest is distinct from a.digest or coalesce(e.kind,a.kind)='category'
)
select 'unit_review_diagnostic/'||kind||'/'||category||'/'||object_name||'/'||attribute check_name,
 expected_sha256 is not distinct from actual_sha256 passed,
 'expected='||coalesce(expected_sha256,'ABSENT')||';actual='||coalesce(actual_sha256,'ABSENT') detail,
